const targetObject = {
  secret: "Hidden Treasure",
  age: 25
};

const handler = {
  // Intercepting GET requests
  get(target, prop, receiver) {
    if (prop === 'secret') {
      return "ACCESS DENIED";
    }
    // Fall back to default behavior
    return Reflect.get(target, prop, receiver);
  },

  // Intercepting SET requests
  set(target, prop, value, receiver) {
    if (prop === 'age' && typeof value !== 'number') {
      throw new TypeError("Age must be a number!");
    }
    console.log(`Setting ${prop} to ${value}`);
    return Reflect.set(target, prop, value, receiver);
  }
};

const proxyObj = new Proxy(targetObject, handler);

console.log(proxyObj.age);    // 25
console.log(proxyObj.secret); // "ACCESS DENIED" (Intercepted!)

proxyObj.age = 26; // Logs: "Setting age to 26"

try {
  proxyObj.age = "Twenty Six"; // Throws TypeError!
} catch (e) {
  console.log(e.message);
}
